using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(Secret)) ti.CreateObject = null; } }
    }
};

// Person IS available via the resolver
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {found!.Type.Name}");
else
    Console.WriteLine("\nPerson metadata not available");

// With a resolver that resolves nothing, TryGetTypeInfo returns false
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → resolves nothing
};

if (empty.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("Secret metadata available (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo(Secret) returned false — no exception thrown");

// Types
public record Person(string Name, int Age);
public record Secret(string Value);

